"use strict";window.addEventListener("load",()=>{$("#media-insert-cancel").on("click",()=>{window.close()}),$("#media-insert-ok").on("click",()=>{const e=$("#media-insert-form").get(0).m_url.value;$.getJSON(`https://noembed.com/embed?url=${e}&callback=?`,e=>{!function(e){const t=$("#media-insert-form").get(0);if(null==t)return;const l=window.opener.the_toolbar,{data:n}=l.elements.noembedmedia;n.alignment=$('input[name="alignment"]:checked',t).val(),n.title=t.m_title.value,n.url=t.m_url.value,n.m_object=e,l.elements.noembedmedia.fncall[l.mode].call(l),window.close()}(e.html)}).fail(e=>{globalThis.alert(`${dotclear.external_media.request_error+e.status} ${e.statusText}`)})})});
